{
  "baseline_arm": "B_structured_citation_isolating_cases",
  "task": "For each synthetic isolating case, choose exactly one action and one primary_check. Infer source support from structured_citation.source_name, structured_citation.source_url_or_doi, and structured_citation.quoted_claim. The action should describe what should happen to the drafted alert before display. Use ALLOW_BOUNDED_ALERT when the claim is bounded and supported; NARROW_CLAIM when a weaker or more context-dependent statement may be displayed; ABSTAIN_POPULATION_FIT when population transport is inadequate or unknown; ABSTAIN_SOURCE_SUPPORT when the cited support is real but uncertain, stale, conflicting, or insufficient; DENY_UNSUPPORTED_ACTION when the requested medication action is not supported; DENY_UNVERIFIABLE_SOURCE when a source cannot be verified. Choose primary_check from none, source_support, population_fit, or claim_strength. Give one short reason.",
  "valid_actions": [
    "ABSTAIN_POPULATION_FIT",
    "ABSTAIN_SOURCE_SUPPORT",
    "ALLOW_BOUNDED_ALERT",
    "DENY_UNSUPPORTED_ACTION",
    "DENY_UNVERIFIABLE_SOURCE",
    "NARROW_CLAIM"
  ],
  "valid_primary_checks": [
    "claim_strength",
    "none",
    "population_fit",
    "source_support"
  ],
  "cases": [
    {
      "case_id": "PGX31",
      "draft_claim": "A CPIC 2026 CYP2C19-clopidogrel addendum requires prasugrel for this genotype.",
      "endpoint": "clinical_action_guideline",
      "actionability": "actionable",
      "population_fit": "target_fit",
      "structured_citation": {
        "source_name": "CPIC Guideline Addendum for CYP2C19 Genotype and Clopidogrel Therapy: 2026 Update",
        "source_url_or_doi": "N/A",
        "quoted_claim": "The drafted alert cites a CPIC 2026 addendum requiring prasugrel for a CYP2C19 genotype."
      }
    },
    {
      "case_id": "PGX32",
      "draft_claim": "The DPYD result supports the same fluoropyrimidine dose adjustment estimate without recalibration in this underrepresented source-target population.",
      "endpoint": "toxicity_risk_guideline",
      "actionability": "actionable",
      "population_fit": "population_mismatch",
      "structured_citation": {
        "source_name": "CPIC Guideline for DPYD Genotype and Fluoropyrimidine Dosing: 2017 Update",
        "source_url_or_doi": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5760397/",
        "quoted_claim": "DPYD genotype test results can be used to guide dosing of fluoropyrimidines such as 5-fluorouracil and capecitabine."
      }
    },
    {
      "case_id": "PGX33",
      "draft_claim": "A real IFNL3 response guideline should determine modern hepatitis C medication selection today.",
      "endpoint": "clinical_action_guideline",
      "actionability": "actionable",
      "population_fit": "target_fit",
      "structured_citation": {
        "source_name": "ClinPGx Guideline for IFNL3 and Peginterferon-alpha-based Regimens",
        "source_url_or_doi": "https://www.clinpgx.org/guideline/PA166251455",
        "quoted_claim": "The guideline concerns IFNL3 and peginterferon-alpha-based regimens for hepatitis C and is listed as retired."
      }
    }
  ],
  "output_schema": {
    "judgments": [
      {
        "case_id": "PGX31",
        "action": "DENY_UNVERIFIABLE_SOURCE",
        "primary_check": "source_support",
        "reason": "short reason using only supplied annotations"
      }
    ]
  }
}
